e = 3
c = 1500505271063454285296134807293480483534368314560076911880887724555410302299990160684413547064146290646443165031721129866487538027494703449890787521125

# Integer cube root via binary search
lo, hi = 0, 1
while hi ** 3 <= c:
    lo = hi
    hi *= 2

while lo < hi:
    mid = (lo + hi + 1) // 2
    if mid ** 3 <= c:
        lo = mid
    else:
        hi = mid - 1

m = lo

# Convert integer to bytes
num_bytes = (m.bit_length() + 7) // 8
plaintext = m.to_bytes(num_bytes, 'big').decode('utf-8')
print("Decoded Plaintext:", plaintext)
